INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa77f-0ed2-76f7-97a7-9081e9270891'::uuid, '019f9df7-a2a2-78ab-b1d6-52be9d287151'::uuid, 'Polygon angles', 'For any polygon, exterior angles always total 360 degrees. That single fact solves most polygon questions.', ARRAY['Interior and exterior angles at a vertex add to 180 degrees', 'The exterior angles of any polygon sum to 360 degrees', 'In a regular polygon all exterior angles are equal']::text[], ARRAY['{"note":"n is the number of sides.","label":"Interior angle sum","expression":"(n - 2) x 180 degrees"}'::jsonb, '{"note":"Rearranges to n = 360 / exterior angle.","label":"Regular polygon exterior angle","expression":"360 / n degrees"}'::jsonb]::text[], ARRAY['{"steps":["Let the angles be 5x and 4x","They sum to 180, so 9x = 180 and x = 20","Exterior angle = 4 x 20 = 80 degrees","n = 360 / 80 = 4.5, which is not a whole number"],"answer":"The number of sides is not an integer, so the polygon cannot exist.","question":"A regular polygon has interior to exterior angle ratio 5:4. Explain why this is impossible."}'::jsonb]::text[], ARRAY['{"fix":"That formula gives the total. Divide by n for one angle of a regular polygon.","mistake":"Using (n - 2) x 180 as the size of one interior angle."}'::jsonb, '{"fix":"Sides must be a whole number. A fraction means the polygon is impossible.","mistake":"Accepting a non-integer number of sides."}'::jsonb]::text[], ARRAY['Work with exterior angles first, they are usually the faster route.', 'Check your final number of sides is a whole number of at least 3.']::text[], ARRAY['t13']::text[], 902, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T06:52:29.778Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa798-94cd-7100-a9bb-18e7f54d1f78'::uuid, '019f9df7-a2a2-78ab-b1d6-52be9d287151'::uuid, 'Angles in parallel lines', 'When a line crosses two parallel lines, three named angle relationships appear again and again.', ARRAY['Corresponding angles sit in matching positions and are equal, forming an F shape', 'Alternate angles sit on opposite sides of the transversal and are equal, forming a Z shape', 'Co-interior angles sit between the parallel lines on the same side and add to 180 degrees', 'These rules only apply when the lines are marked as parallel']::text[], ARRAY['{"note":"F shape, in matching positions on the transversal.","label":"Corresponding angles","expression":"equal"}'::jsonb, '{"note":"Z shape, on opposite sides of the transversal.","label":"Alternate angles","expression":"equal"}'::jsonb, '{"note":"C shape, between the parallel lines on the same side.","label":"Co-interior angles","expression":"add to 180 degrees"}'::jsonb]::text[], ARRAY['{"steps":["Alternate angles are equal, so that angle is 68 degrees","Co-interior angles add to 180 degrees","180 - 68 = 112"],"answer":"Alternate angle 68 degrees, co-interior angle 112 degrees","question":"Two parallel lines are crossed by a transversal and one angle is 68 degrees. Find the alternate angle and the co-interior angle."}'::jsonb]::text[], ARRAY['{"fix":"Corresponding angles form an F shape; alternate angles form a Z shape.","mistake":"Calling equal angles corresponding when they are actually alternate."}'::jsonb, '{"fix":"They add to 180 degrees, and are only equal when both are 90 degrees.","mistake":"Assuming co-interior angles are equal."}'::jsonb, '{"fix":"Look for the arrow markings. Without them these rules do not apply.","mistake":"Using parallel line rules when the lines are not marked parallel."}'::jsonb]::text[], ARRAY['Trace the F, Z and C shapes on the diagram to decide which rule applies.', 'Name the rule in your answer, the reason usually carries its own mark.']::text[], ARRAY['t11']::text[], 903, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T07:20:22.476Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa798-94cd-7126-b8a2-f1c4cb68dab4'::uuid, '019f9df7-a2a2-78ab-b1d6-52be9d287151'::uuid, 'Properties of quadrilaterals', 'Each special quadrilateral has its own set of side, angle and diagonal properties, and naming questions turn on the diagonals.', ARRAY['A square has four equal sides, four right angles, and diagonals that are equal and bisect at right angles', 'A rectangle has equal diagonals that bisect each other, but not at right angles', 'A rhombus has four equal sides and diagonals that bisect at right angles but are unequal', 'A parallelogram has opposite sides equal and parallel and opposite angles equal', 'A kite has two pairs of adjacent equal sides, and one diagonal bisects the other at right angles']::text[], ARRAY['{"note":"True for every quadrilateral.","label":"Angle sum of a quadrilateral","expression":"a + b + c + d = 360 degrees"}'::jsonb, '{"note":"a and b are the parallel sides, h the perpendicular height between them.","label":"Trapezium area","expression":"area = 1/2 (a + b) h"}'::jsonb]::text[], ARRAY['{"steps":["Diagonals crossing at right angles rules out the rectangle and the plain parallelogram","Equal diagonals would make it a square, but here they are unequal","The remaining shape with these properties is a rhombus"],"answer":"A rhombus","question":"A quadrilateral has diagonals that bisect each other at right angles but are not equal in length. Name it and justify your answer."}'::jsonb]::text[], ARRAY['{"fix":"A rhombus has diagonals that bisect at right angles but are different lengths. Equal diagonals means a square or rectangle.","mistake":"Saying a rhombus has equal diagonals."}'::jsonb, '{"fix":"Only use properties that are marked or stated in the question.","mistake":"Assuming a shape is a square because it looks like one."}'::jsonb, '{"fix":"Compare them on three checks: equal sides, right angles, and what the diagonals do.","mistake":"Mixing up rhombus, rectangle and parallelogram properties."}'::jsonb]::text[], ARRAY['Build a table of the six quadrilaterals against sides, angles and diagonals, and learn it.', 'For naming questions, quote the property that rules out the other shapes.']::text[], ARRAY['t13']::text[], 904, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T07:20:22.476Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa798-94cd-7323-b7a3-4c838289aef8'::uuid, '019f9df7-a2a2-78ab-b1d6-52be9d287151'::uuid, 'Perpendicular and angle bisector constructions', 'Two ruler-and-compass constructions come up regularly: the perpendicular bisector of a line and the bisector of an angle.', ARRAY['Every point on a perpendicular bisector is the same distance from both end points', 'Every point on an angle bisector is the same distance from both arms of the angle', 'Construction arcs must be left visible because they show the method', 'Set the compass to more than half the line length so the arcs actually cross']::text[], ARRAY['{"note":"Cuts the line in half at 90 degrees.","label":"Perpendicular bisector","expression":"equal arcs from both end points, then join the crossing points"}'::jsonb, '{"note":"Splits the angle into two equal halves.","label":"Angle bisector","expression":"one arc across both arms, then equal arcs from those two points"}'::jsonb]::text[], ARRAY['{"steps":["Open the compass to more than half of AB","Draw arcs above and below the line from A, then repeat from B with the same radius","Join the two points where the pairs of arcs cross"],"answer":"The line drawn is the perpendicular bisector of AB, which is the required locus","question":"Describe how to construct the locus of points equidistant from two points A and B."}'::jsonb]::text[], ARRAY['{"fix":"The arcs show your method and carry marks. Leave them on the page.","mistake":"Rubbing out the construction arcs to tidy up the diagram."}'::jsonb, '{"fix":"Keep the same radius for each pair of arcs.","mistake":"Changing the compass width partway through a construction."}'::jsonb, '{"fix":"Construct means ruler and compasses only.","mistake":"Measuring with a protractor when the question says construct."}'::jsonb]::text[], ARRAY['Use a sharp pencil and draw the arcs long enough to cross clearly.', 'Equidistant from two points means perpendicular bisector; equidistant from two lines means angle bisector.']::text[], ARRAY['t14']::text[], 905, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T07:20:22.476Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa77f-0ed2-7889-a1bc-441d9ff8f55c'::uuid, '019f9df7-a2a2-78c7-aa4b-565799c65ce4'::uuid, 'Congruence and similarity', 'Congruent triangles are the same shape and size. Similar triangles have the same shape with corresponding sides in proportion.', ARRAY['Congruence tests: SSS, SAS, ASA, AAS, RHS (state the test used)', 'Similarity tests: AAA (two equal angles suffice), SSS sides proportional, SAS sides proportional with included equal angle', 'Congruent figures are identical in shape and size; similar figures share shape but not necessarily size']::text[], ARRAY['{"note":"Match corresponding sides carefully.","label":"Length scale factor","expression":"k = corresponding length on larger / corresponding length on smaller"}'::jsonb, '{"note":"Square or cube the length factor for similar figures.","label":"Area and volume scaling","expression":"area ratio = k^2; volume ratio = k^3"}'::jsonb]::text[], ARRAY['{"steps":["Two corresponding sides equal with the included angle equal","This is SAS congruence"],"answer":"SAS","question":"State which congruence rule applies when two triangles have two equal sides and the included equal angle."}'::jsonb, '{"steps":["Length scale factor k = 10 / 4 = 2.5","Volume scale factor = k^3 = 15.625","Larger volume = 32 x 15.625 = 500"],"answer":"500 cm^3","question":"Two similar solids have heights 4 cm and 10 cm. The smaller has volume 32 cm^3. Find the volume of the larger."}'::jsonb]::text[], ARRAY['{"fix":"AAA proves similarity, not congruence; sizes may differ.","mistake":"Claiming congruence from AAA alone."}'::jsonb, '{"fix":"Square it for area and cube it for volume.","mistake":"Using the length scale factor directly for area or volume."}'::jsonb]::text[], ARRAY['Sketch both triangles the same way round before pairing sides.', 'In proofs, name the triangles in corresponding vertex order and state the test (e.g. SAS).']::text[], ARRAY['t13']::text[], 1001, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T06:52:29.778Z'::timestamptz) ON CONFLICT (id) DO NOTHING;